public final class PlaybackRequestGate {
    private PlaybackRequestGate() {
    }

    public static Decision decide(@Nullable String activeUrl, boolean activeStopped, @Nullable String pendingUrl, String requestedUrl) {
        if (activeUrl != null && !activeStopped && activeUrl.equals(requestedUrl)) {
            return Decision.REFRESH;
        }
        if (pendingUrl != null && pendingUrl.equals(requestedUrl)) {
            return Decision.IGNORE;
        }
        return Decision.START;
    }

    public static Decision decide(@Nullable String activeUrl, boolean activeStopped, @Nullable String pendingUrl, String requestedUrl, @Nullable Long previousGeneration, long requestedGeneration) {
        if (previousGeneration == null || previousGeneration != requestedGeneration) {
            return Decision.START;
        }
        return PlaybackRequestGate.decide(activeUrl, activeStopped, pendingUrl, requestedUrl);
    }

    public static enum Decision {
        START,
        REFRESH,
        IGNORE;

    }
}

